public sealed partial class BedMap : Map<Bed, BedModel>
{
    protected override void Configure(IMapBuilder<Bed, BedModel> map) => map
        // Not a column of its own: the state column read as a bed.
        .Member(m => m.BedState, e => (EnumBedState)e.State)
        // Not loaded on this path, and saying so keeps it accounted for.
        .Ignore(m => m.BuildingUnit, m => m.Department);
}

// Every other member matches by name, so nothing is said about it. Configure is READ,
// not run: the generator writes the tree into a second part of this class, and the
// generated file is where you go to see what a member got.
